# ---------------------------------------------------------------- arapski
AR_DIACRITICS = re.compile(r"[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED\u08D3-\u08FF]")
AR_TATWEEL    = re.compile(r"\u0640")
AR_PUNCT      = re.compile(r"[^\w\s\u0600-\u06FF]", re.UNICODE)

def norm_ar(s: str) -> str:
    """Normalizacija arapskog za poredjenje: skini dijakritiku, alef varijante, tatweel."""
    if not s: return ""
    s = AR_TATWEEL.sub("", s)
    s = AR_DIACRITICS.sub("", s)
    # alef varijante -> alef
    s = re.sub(r"[\u0622\u0623\u0625\u0671]", "\u0627", s)
    s = s.replace("\u0649", "\u064A")   # alef maksura -> ya
    s = s.replace("\u0629", "\u0647")   # ta marbuta -> ha (priblizno)
    s = s.replace("\u0624", "\u0648").replace("\u0626", "\u064A")
    s = AR_PUNCT.sub(" ", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s

def words_ar(s: str):
    return [w for w in norm_ar(s).split(" ") if w]

_AR_KEEP = re.compile(r"[^\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]")

def ara_disp(w: str) -> str:
    """Rijec za PRIKAZ: zadrzi harakate (tacke su dio slova), skini tatweel i ne-arapske znake."""
    if not w:
        return ""
    return _AR_KEEP.sub("", AR_TATWEEL.sub("", w))

def lev_ratio(a: str, b: str) -> float:
    """Levenshtein similarity 0..1 (bez zavisnosti)."""
    if a == b: return 1.0
    if not a or not b: return 0.0
    la, lb = len(a), len(b)
    if la > 60 or lb > 60:      # skrati za dugacke rijeci
        a, b, la, lb = a[:60], b[:60], min(la,60), min(lb,60)
    prev = list(range(lb + 1))
    for i, ca in enumerate(a, 1):
        cur = [i] + [0] * lb
        for j, cb in enumerate(b, 1):
            cur[j] = min(prev[j] + 1, cur[j-1] + 1, prev[j-1] + (ca != cb))
        prev = cur
    return 1.0 - prev[lb] / max(la, lb)

# ---------------------------------------------------------------- bosanski korektor
# Uredi bosanski tekst: velika slova na pocetku recenice, ciscenje razmaka,
# ispravni navodnici, tacke/upitnik/zapeta bez razmaka prije.
BS_SMALL_OK = {"i", "u", "na", "za", "od", "do", "sa", "po", "je", "se", "ne",
               "da", "li", "te", "ni", "ali", "koji", "koja", "koje", "a", "o",
               "sve", "svih", "jer", "kad", "kada", "sto", "što", "ko", "šta"}

def korekt_bs(s: str, ajet: bool = True) -> str:
    """Uredi bosanski tekst. ajet=True dodaje zavrsnu tacku; ajet=False (spojeni ajeti) ostavlja vezu."""
    if not s:
        return ""
    s = s.replace("\u00a0", " ")
    s = re.sub(r"\s+", " ", s).strip()
    # ukloni duplu interpunkciju (npr. ",." ".," "..")
    s = re.sub(r"[,;:]+(?=\s*[.!?])", "", s)
    s = re.sub(r"([.!?])\s*[,;:]+", r"\1", s)
    # razmak PRIJE interpunkcije -> skini
    s = re.sub(r"\s+([,.;:!?،؛])", r"\1", s)
    # osiguraj razmak POSLIJE interpunkcije
    s = re.sub(r"([,;:])(?=\S)", r"\1 ", s)
    # navodnici / ciscenje
    s = s.replace(" ,", ",").replace(" .", ".").replace(" ?", "?").replace(" !", "!")
    # veliko slovo na pocetku teksta
    if s:
        s = s[0].upper() + s[1:]
    # veliko slovo poslije . ! ? (pocetak nove recenice)
    s = re.sub(r"([.!?]\s+)([a-zčćžšđ])",
               lambda m: m.group(1) + m.group(2).upper(), s, flags=re.UNICODE)
    # ocisti interpunkciju na kraju + duple
    s = re.sub(r"\s+([,.;:!?])", r"\1", s)
    if ajet:
        # pojedinacni ajet: skini zavrsni zarez/crticu/crticu-razmak pa dodaj tacku
        s = re.sub(r"[\s,;:]*[\-–—]\s*$", "", s)
        s = re.sub(r"[,;:\-–—]\s*$", "", s)
        s = re.sub(r"\.{2,}", ".", s).strip()
        if s and s[-1] not in ".!?…":
            s += "."
    return s

def stavi_ajete_zajedno(rows) -> str:
    """Spoji prijevode ajeta u jedan tekst (Korkut veze zarezima -> zadrzi ih, samo ocisti razmake)."""
    dijelovi = []
    for r in rows:
        t = (r["tekst_bs"] if isinstance(r, dict) else r[0]) or ""
        t = korekt_bs(t, ajet=False).strip()
        # skini zavrsni zarez/crticu da se ne duplira pri spajanju
        t = re.sub(r"[,;:\-–—]\s*$", "", t).strip()
        if t:
            dijelovi.append(t)
    out = ", ".join(dijelovi)
    out = re.sub(r"\s+", " ", out).strip()
    # velika slova SAMO poslije . ! ? (ne poslije zareza)
    out = re.sub(r"([.!?]\s+)([a-zčćžšđ])",
                 lambda m: m.group(1) + m.group(2).upper(), out, flags=re.UNICODE)
    if out:
        out = out[0].upper() + out[1:]
    # na kraju tacka
    out = re.sub(r"[,;:\-–—]\s*$", "", out)
    if out and out[-1] not in ".!?…":
        out += "."
    # ocisti duple zapete/razmake
    out = re.sub(r",\s*,", ",", out)
    out = re.sub(r"\s+\.", ".", out)
    return out

# ---------------------------------------------------------------- whisper
_model = None
_model_lock = threading.Lock()

def get_model():
    global _model
    with _model_lock:
        if _model is None:
            from faster_whisper import WhisperModel
            # probaj tarteel CT2, pa base
            cand = [
                os.path.join(MODELS, "tarteel-base-ar-ct2"),
                os.path.join(MODELS, "tarteel-base-ar"),
                "base",
            ]
            for c in cand:
                try:
                    if c == "base" or os.path.exists(os.path.join(c, "model.bin")):
                        print(f"[whisper] ucitavam: {c}", flush=True)
                        _model = WhisperModel(c, device="cpu", compute_type="int8")
                        break
                except Exception as e:
                    print(f"[whisper] {c} fail: {e}", flush=True)
            if _model is None:
                _model = WhisperModel("base", device="cpu", compute_type="int8")
        return _model

STT_URL = os.environ.get("GAMA_STT_URL", "http://127.0.0.1:8077")

def transcribe_gpu(path):
    """Arapski preko GAMA GPU whisper (Vast :8077, large-v3-turbo)."""
    import urllib.request
    with open(path, "rb") as f:
        data = f.read()
    req = urllib.request.Request(STT_URL + "/?lang=ar", data=data,
                                 headers={"Content-Type": "application/octet-stream"})
    with urllib.request.urlopen(req, timeout=45) as r:
        d = json.loads(r.read().decode())
    return (d.get("text", "") or "").strip()

def transcribe(path):
    """Arapski: prvo GAMA GPU (brzo + tacno), pa lokalni CPU fallback."""
    # 1) GAMA GPU (Vast large-v3-turbo)
    if STT_URL:
        try:
            txt = transcribe_gpu(path)
            if len(words_ar(txt)) >= 1:
                return txt, 0.9
        except Exception as e:
            print(f"[transcribe] gpu fail: {e}", flush=True)
    # 2) lokalni CPU fallback (tarteel/base)
    m = get_model()
    txt, info = "", None
    try:
        segs, info = m.transcribe(path, language="ar", beam_size=1,
                                  condition_on_previous_text=False,
                                  vad_filter=True,
                                  vad_parameters=dict(min_silence_duration_ms=180,
                                                      speech_pad_ms=120))
        txt = " ".join(s.text.strip() for s in segs).strip()
    except Exception as e:
        print(f"[transcribe] vad fail: {e}", flush=True)
    if len(words_ar(txt)) < 2:
        try:
            segs, info = m.transcribe(path, language="ar", beam_size=1,
                                      condition_on_previous_text=False,
                                      vad_filter=False)
            txt2 = " ".join(s.text.strip() for s in segs).strip()
            if len(words_ar(txt2)) > len(words_ar(txt)):
                txt = txt2
        except Exception as e:
            print(f"[transcribe] novad fail: {e}", flush=True)
    return txt, getattr(info, "language_probability", 0.0)

# ---------------------------------------------------------------- poredjenje
def compare(recited: str, expected: str):
    """Uporedi recitaciju s ajetom. Vrati skor + word-level diff.
    Poredjenje ide po normalizovanim rijecima (bez harakata), a za PRIKAZ se
    cuvaju originalne rijeci S HARAKATIMA (tacke su dio slova)."""
    epairs = [(ara_disp(w), norm_ar(w)) for w in (expected or "").split()]
    epairs = [p for p in epairs if p[1]]
    rpairs = [(ara_disp(w), norm_ar(w)) for w in (recited or "").split()]
    rpairs = [p for p in rpairs if p[1]]
    ew = [p[1] for p in epairs]      # normalizovano (za poredjenje)
    rw = [p[1] for p in rpairs]
    edisp = [p[0] for p in epairs]   # s harakatima (za prikaz)
    rdisp = [p[0] for p in rpairs]
    if not ew:
        return {"skor": 0, "greske": [], "rijec_po_rijec": []}

    # DP alignment (word-level Levenshtein s fuzzy matchem >= 0.7)
    n, mm = len(ew), len(rw)
    INF = 10**9
    dp = [[0]*(mm+1) for _ in range(n+1)]
    op = [[None]*(mm+1) for _ in range(n+1)]
    for i in range(n+1): dp[i][0] = i; op[i][0] = "del"
    for j in range(mm+1): dp[0][j] = j; op[0][j] = "ins"
    for i in range(1, n+1):
        for j in range(1, mm+1):
            sim = lev_ratio(ew[i-1], rw[j-1])
            # KOKA_FIX_V2: blaze pragovi. Arapski osnovni model cesto promasi dijakritiku
            # i teske suglasnike -> strogi prag je pravio LAZNE greske (npr. Fatiha).
            # Kratke rijeci (<=3) ostaju stroze (0.55), srednje 0.62, duze 0.60.
            w = ew[i-1]
            if len(w) <= 3:
                thr = 0.55
            elif len(w) <= 6:
                thr = 0.62
            else:
                thr = 0.60
            cost = 0 if sim >= thr else 1
            best = dp[i-1][j-1] + cost
            o = "ok" if cost == 0 else "sub"
            if dp[i-1][j] + 1 < best: best, o = dp[i-1][j] + 1, "del"
            if dp[i][j-1] + 1 < best: best, o = dp[i][j-1] + 1, "ins"
            dp[i][j], op[i][j] = best, o
    # rekonstrukcija
    detail, greske = [], []
    i, j = n, mm
    while i > 0 or j > 0:
        o = op[i][j]
        if o == "ok":
            detail.append({"tip":"ok","ocekivano":edisp[i-1],"recitovano":rdisp[j-1]}); i-=1; j-=1
        elif o == "sub":
            detail.append({"tip":"greska","ocekivano":edisp[i-1],"recitovano":rdisp[j-1]})
            greske.append({"poz":i,"ocekivano":edisp[i-1],"recitovano":rdisp[j-1]}); i-=1; j-=1
        elif o == "del":
            detail.append({"tip":"preskoceno","ocekivano":edisp[i-1],"recitovano":""})
            greske.append({"poz":i,"ocekivano":edisp[i-1],"recitovano":"(preskočeno)"}); i-=1
        else:
            detail.append({"tip":"dodatno","ocekivano":"","recitovano":rdisp[j-1]}); j-=1
    detail.reverse()
    tacnih = sum(1 for d in detail if d["tip"]=="ok")
    skor = round(100.0 * tacnih / max(1, n))
    return {"skor": skor, "tacnih": tacnih, "ukupno": n,
            "recitovano": recited, "ocekivano": expected,
            "greske": greske, "rijec_po_rijec": detail}

# ---------------------------------------------------------------- DB
def db():
    con = sqlite3.connect(DB)
    con.row_factory = sqlite3.Row
    return con

def q(sql, args=()):
    con = db()
    try:
        return [dict(r) for r in con.execute(sql, args).fetchall()]
    finally:
        con.close()

# ---------------------------------------------------------------- fajlovi + audio proxy
FONT_DIR = os.path.join(HERE, "data", "fonts")
AUDIO_CACHE = os.path.join(HERE, "data", "audio_cache")
CTYPE = {".woff2": "font/woff2", ".woff": "font/woff", ".ttf": "font/ttf",
         ".mp3": "audio/mpeg", ".png": "image/png", ".svg": "image/svg+xml"}

def read_file(path):
    with open(path, "rb") as fh:
        return fh.read()

def proxy_audio(url, name):
    """Serviraj ajet MP3 s nase adrese (same-origin) + lokalni kes.
    Tako 'Slušaj karija' radi i kad telefon ne moze direktno na everyayah.com."""
    import urllib.request, hashlib
    if not url:
        return None
    os.makedirs(AUDIO_CACHE, exist_ok=True)
    key = hashlib.md5(url.encode()).hexdigest()[:16] + "_" + re.sub(r"[^\w.-]", "_", name)[-40:]
    path = os.path.join(AUDIO_CACHE, key)
    if not (os.path.exists(path) and os.path.getsize(path) > 1000):
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 GAMA-HIFZ"})
            with urllib.request.urlopen(req, timeout=25) as r:
                data = r.read()
            if not data or len(data) < 1000:
                return None
            tmp = path + ".tmp"
            with open(tmp, "wb") as fh:
                fh.write(data)
            os.replace(tmp, path)
        except Exception as e:
            print(f"[audio] proxy fail {url}: {e}", flush=True)
            return None
    return path

# ---------------------------------------------------------------- napredak + kes
def init_extra():
    con = db()
    try:
        con.execute("CREATE TABLE IF NOT EXISTS savjet_cache (k TEXT PRIMARY KEY, savjet TEXT, ts INTEGER)")
        con.execute("CREATE TABLE IF NOT EXISTS napredak (id INTEGER PRIMARY KEY AUTOINCREMENT,"
                    " cid TEXT, ts INTEGER, mod TEXT, sura INT, ajet INT, skor INT, n INT)")
        con.commit()
    finally:
        con.close()

def record_napredak(cid, mod, sura, ajet, skor, n):
    if not cid:
        return
    con = db()
    try:
        con.execute("INSERT INTO napredak (cid,ts,mod,sura,ajet,skor,n) VALUES (?,?,?,?,?,?,?)",
                    (cid, int(time.time()), mod, int(sura), int(ajet), int(skor), int(n)))
        con.commit()
    finally:
        con.close()

def napredak_stats(cid):
    if not cid:
        return None
    con = db()
    try:
        r = con.execute("SELECT COUNT(*) c, AVG(skor) a, MAX(skor) m FROM napredak WHERE cid=?", (cid,)).fetchone()
        red = con.execute("SELECT sura, ajet, skor, ts FROM napredak WHERE cid=? ORDER BY id DESC LIMIT 5", (cid,)).fetchall()
        po = con.execute("SELECT sura, COUNT(*) c, CAST(AVG(skor) AS INT) a FROM napredak WHERE cid=?"
                         " GROUP BY sura ORDER BY a DESC LIMIT 3", (cid,)).fetchall()
        return {"ukupno": r["c"], "prosjek": round(r["a"] or 0), "najbolji": r["m"] or 0,
                "zadnji": [dict(x) for x in red], "po_surama": [dict(x) for x in po]}
    finally:
        con.close()

# ---------------------------------------------------------------- GAMA LLM (nasa moc)
MOTOR = os.environ.get("HIFZ_MOTOR_URL", os.environ.get("GAMA_MOTOR", "")).strip()  # OpenAI-compatible /v1/chat/completions (npr. Ollama, vLLM, bilo koji free endpoint)

def llm_savjet(tekst, skor):
    """Kratak bosanski savjet ucitelja Kur'ana preko GAMA motora (:8000). Uz kes."""
    import urllib.request, hashlib
    k = hashlib.md5((str(tekst) + "|" + str(skor)).encode()).hexdigest()
    try:
        con = db()
        try:
            row = con.execute("SELECT savjet FROM savjet_cache WHERE k=?", (k,)).fetchone()
            if row and row["savjet"]:
                return row["savjet"]
        finally:
            con.close()
    except Exception:
        pass
    prompt = (
        "Ti si blag i strucan ucitelj Kur'ana (hifz). Ucenik je upravo recitovao i ima ove greske:\n"
        + (tekst or "nema detalja") +
        "\nUkupan skor: %s%%.\n"
        "Napiši NA BOSANSKOM (ijekavica, latinica) 2-3 kratke recenice: konkretan savjet kako ispraviti "
        "greske (izgovor slova / tajweed) i kratku ohrabrujucu poruku. Bez uvoda, bez ponavljanja greska."
    ) % skor
    body = json.dumps({
        "model": "agent",
        "messages": [{"role": "user", "content": prompt}],
        "temperature": 0.3, "max_tokens": 240,
    }).encode()
    req = urllib.request.Request(MOTOR + "/v1/chat/completions", data=body,
                                 headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=60) as r:
        d = json.loads(r.read().decode())
    out = (d["choices"][0]["message"]["content"] or "").strip()
    try:
        con = db()
        try:
            con.execute("INSERT OR REPLACE INTO savjet_cache (k,savjet,ts) VALUES (?,?,?)",
                        (k, out, int(time.time())))
            con.commit()
        finally:
            con.close()
    except Exception:
        pass
    return out

